add_action( 'woocommerce_product_query', 'perfectpixel_hide_free_products' );

function perfectpixel_hide_free_products( $q ) {
	$meta_query   = (array) $q->get( 'meta_query' );
	$meta_query[] = array(
		'relation' => 'OR',
		array(
			'key'     => '_price',
			'value'   => 0,
			'compare' => '>',
			'type'    => 'DECIMAL(10,4)',
		),
		array(
			'key'     => '_price',
			'compare' => 'NOT EXISTS',
		),
	);
	$q->set( 'meta_query', $meta_query );
}
